mod analyze;
mod band_table;
mod bands;
mod benches;
mod binary;
mod child;
mod config;
mod dither;
mod figures;
mod freq;
mod freqctl;
mod gauge;
mod harness;
mod host;
mod inhibit;
mod init_config;
mod inner;
mod linear_regression;
mod md_fence;
mod pin;
mod probe;
mod qualify;
mod record;
mod report;
mod resolution;
mod run_config;
mod runs;
mod series;
