828	/// Whether a positional names a config file: it ends in a carrier's extension, which no bench
829	/// name does, so the two never collide. A bare name stays a bench, since falling back to a
830	/// config would turn a mistyped bench into a file lookup.
831	fn is_config_arg(word: &str) -> bool {
832	    std::path::Path::new(word)
833	        .extension()
834	        .is_some_and(|e| e == "md" || e == "toml")
835	}
