870	/// Refuse a bench list holding a command word other than `all`. A command word runs alone and
871	/// positionally, so in `--benches` or the config `benches` it would otherwise reach bench
872	/// resolution and read as an unknown bench.
873	fn check_bench_words(words: &[String]) -> Result<(), String> {
874	    match words
875	        .iter()
876	        .find(|w| *w != "all" && COMMAND_WORDS.iter().any(|(c, _)| c == w))
877	    {
878	        Some(word) => Err(format!(
879	            "benches: '{word}' is a command word, not a bench: run it as '{BIN_NAME} {word}'"
880	        )),
881	        None => Ok(()),
882	    }
883	}
