909	/// What this host lacks for a run that pins the clock when `pin_clock` and pins `spec`'s
910	/// placements: the `[freq]` steady state a pin returns to, the permission to write the clock,
911	/// and the profiles the placements name, each a line saying what is missing. Empty when the
912	/// host is ready, and when the run pins nothing.
913	fn readiness_gaps(config: &config::Config, pin_clock: bool, spec: Option<&str>) -> Vec<String> {
914	    let first = |e: String| e.lines().next().unwrap_or_default().to_string();
915	    let mut gaps = Vec::new();
916	    if pin_clock {
917	        if let Err(e) = freqctl::check_steady(config.freq.as_ref()) {
918	            gaps.push(format!("the clock: {}", first(e)));
919	        }
920	        if !setup::permissions_ready() {
921	            gaps.push(
922	                "the permissions: the cpufreq files a pin writes are not yours to write"
923	                    .to_string(),
924	            );
925	        }
926	    }
927	    // Only a host with no profiles at all lacks setup's: a name a set-up host does not declare, or
928	    // one misspelled, is the ordinary placement error, which setup could not fix.
929	    if config.profiles.is_empty()
930	        && let Some(s) =
931	            spec.filter(|s| !s.is_empty() && !s.starts_with(|c: char| c.is_ascii_digit()))
932	        && let Err(e) = config.placements(s)
933	    {
934	        gaps.push(format!("the placement: {}", first(e)));
935	    }
936	    gaps
937	}
