940	/// version, which the banner would have shown, so a failure from a stale install names the build
941	/// that failed. Hashed only when a run fails this early.
942	fn binary_line() -> String {
943	    match binary::Binary::this() {
944	        Ok(b) => format!(
945	            "  binary {}, {BIN_NAME} {}",
946	            b.short(),
947	            env!("CARGO_PKG_VERSION")
948	        ),
949	        Err(e) => format!("  binary unreadable: {e}"),
950	    }
