1496	    let (pin_cpus_spec, pin_cpus_src) = match run_config::layered_opt(
1497	        cli.pin_cpus.clone(),
1498	        "--pin-cpus",
1499	        config.pin_cpus.clone(),

file.content:
        .chain(configs)
        .collect()
}

/// The config files `typed` could become: the `.md` and `.toml` files in the directory it
/// names so far whose names start as it does. None for an empty `typed`, where every README
/// in the directory would crowd the bench names.
fn config_files(typed: &str) -> Vec<String> {
    if typed.is_empty() {
        return Vec::new();
    }
    let (dir, prefix) = match typed.rsplit_once('/') {
        Some((dir, prefix)) => (format!("{dir}/"), prefix),
        None => (String::new(), typed),
    };
    let listing = match std::fs::read_dir(if dir.is_empty() { "." } else { &dir }) {
        Ok(listing) => listing,
        Err(_) => return Vec::new(),
    };
    let mut files: Vec<String> = listing
        .filter_map(|entry| entry.ok()?.file_name().into_string().ok())
        .filter(|name| name.starts_with(prefix) && is_config_arg(name))
        .map(|name| format!("{dir}{name}"))
        .collect();
    files.sort();
    files
}

/// Whether a positional names a config file: it ends in a carrier's extension, which no bench
/// name does, so the two never collide. A bare name stays a bench, since falling back to a
/// config would turn a mistyped bench into a file lookup.
fn is_config_arg(word: &str) -> bool {
    std::path::Path::new(word)
        .extension()
        .is_some_and(|e| e == "md" || e == "toml")
}

/// Move a config file among the positionals into `--config`, so `iiac-perf queue.md` is
/// `iiac-perf --config queue.md`, the common line without the flag. `init-config` and
/// `update-config` keep theirs, their one positional being a file to write.
fn take_config_arg(cli: &mut Cli) -> Result<(), String> {
    if cli
        .benches
        .first()
        .is_some_and(|w| w == "init-config" || w == "update-config")
    {
        return Ok(());
    }
    let (files, names): (Vec<String>, Vec<String>) =
        cli.benches.drain(..).partition(|w| is_config_arg(w));
    cli.benches = names;
    let mut files = files.into_iter();
    let Some(file) = files.next() else {
        return Ok(());
    };
    if let Some(second) = files.next() {
        return Err(format!(
            "'{file}' and '{second}' both name the run's config: a run has one"
        ));
    }
    if let Some(flag) = &cli.config {
        return Err(format!(
            "'{file}' and --config {} both name the run's config: keep one",
            flag.display()
        ));
    }
    cli.config = Some(file.into());
    Ok(())
}

/// Refuse a bench list holding a command word other than `all`. A command word runs alone and
/// positionally, so in `--benches` or the config `benches` it would otherwise reach bench
/// resolution and read as an unknown bench.
fn check_bench_words(words: &[String]) -> Result<(), String> {
    match words
        .iter()
        .find(|w| *w != "all" && COMMAND_WORDS.iter().any(|(c, _)| c == w))
    {
        Some(word) => Err(format!(
            "benches: '{word}' is a command word, not a bench: run it as '{BIN_NAME} {word}'"
        )),
        None => Ok(()),
    }
}

/// An on/off flag's optional value, `--verbose=no`, so the line can cancel what a config file
/// turned on. The bare flag is `yes`.
fn parse_yes_no(value: &str) -> Result<bool, String> {
    match value {
        "yes" => Ok(true),
        "no" => Ok(false),
        other => Err(format!("{other:?} is not yes or no")),
    }
}

/// Default seconds of measurement per run: 0.25 s, the project config's and the default since
/// 2026-10-01, ten runs of it costing about 17 s a bench with the sleeps.
const DEFAULT_DURATION: f64 = 0.25;
const DEFAULT_BAND_LABELS: bands::BandLabels = bands::BandLabels::Both;
/// Default decimals on the time columns: 3, the picosecond recording floor, which a 2 ns ring
/// needs to show a difference.
const DEFAULT_DECIMALS: u8 = 3;
/// Default placement: the nearest the host declares, `smt` where a core has two threads and
/// `ccx` where it has one, since a comparison pins and a name suits every host.
const DEFAULT_PIN_CPUS: &str = "nearest";
/// Default clock pin: the host's own `pin_mhz`, else its base clock, since a pinned clock is what
/// makes a claim honest rather than tight.
const DEFAULT_PIN_FREQ: config::PinFreq = config::PinFreq::PinMhz;

/// What this host lacks for a run that pins the clock when `pin_clock` and pins `spec`'s
/// placements: the `[freq]` steady state a pin returns to, the permission to write the clock,
/// and the profiles the placements name, each a line saying what is missing. Empty when the
/// host is ready, and when the run pins nothing.
fn readiness_gaps(config: &config::Config, pin_clock: bool, spec: Option<&str>) -> Vec<String> {
    let first = |e: String| e.lines().next().unwrap_or_default().to_string();
    let mut gaps = Vec::new();
    if pin_clock {
        if let Err(e) = freqctl::check_steady(config.freq.as_ref()) {
            gaps.push(format!("the clock: {}", first(e)));
        }
        if !setup::permissions_ready() {
            gaps.push(
                "the permissions: the cpufreq files a pin writes are not yours to write"
                    .to_string(),
            );
        }
    }
    // Only a host with no profiles at all lacks setup's: a name a set-up host does not declare, or
    // one misspelled, is the ordinary placement error, which setup could not fix.
    if config.profiles.is_empty()
        && let Some(s) =
            spec.filter(|s| !s.is_empty() && !s.starts_with(|c: char| c.is_ascii_digit()))
        && let Err(e) = config.placements(s)
    {
        gaps.push(format!("the placement: {}", first(e)));
    }
    gaps
}

/// The line an error that stops a run before its banner ends with: the binary's short hash and
/// version, which the banner would have shown, so a failure from a stale install names the build
/// that failed. Hashed only when a run fails this early.
fn binary_line() -> String {
    match binary::Binary::this() {
        Ok(b) => format!(
            "  binary {}, {BIN_NAME} {}",
            b.short(),
            env!("CARGO_PKG_VERSION")
        ),
        Err(e) => format!("  binary unreadable: {e}"),
    }
}

/// A host not set up for the run: name what it lacks, and on a terminal offer `setup --apply`,
/// then run the same command again once it is set up. Off a terminal, or declined, exit 2 naming
/// the command and the opt-outs.
fn not_set_up(gaps: &[String]) -> ! {
    eprintln!("This host is not set up for this run:");
    for g in gaps {
        eprintln!("  - {g}");
    }
    eprintln!("{}", binary_line());
    let terminal = unsafe { libc::isatty(0) == 1 && libc::isatty(2) == 1 };
    if terminal {
        eprint!("Set it up now with `{BIN_NAME} setup --apply`? [y/N] ");
        let mut answer = String::new();
        // OK: an unreadable answer is no answer, which declines.
        std::io::stdin().read_line(&mut answer).unwrap_or_default();
        if matches!(answer.trim(), "y" | "Y" | "yes") {
            eprintln!();
            let code = setup::run_setup(true);
            if code != 0 {
                std::process::exit(code);
            }
            eprintln!();
            eprintln!("Set up. Running the command again.");
            eprintln!();
            // The same command from the start, reading the config setup just wrote.
            use std::os::unix::process::CommandExt;
            let err = match std::env::current_exe() {
                Ok(exe) => std::process::Command::new(exe)
                    .args(std::env::args_os().skip(1))
                    .exec(),
                Err(e) => e,
            };
            eprintln!("error: running the command again: {err}");
            std::process::exit(1);
        }
    }
    eprintln!(
        "Run `{BIN_NAME} setup` to see what it would do and `{BIN_NAME} setup --apply` to do it, \
         or run unpinned with --pin-cpus \"\" --pin-freq=no."
    );
    std::process::exit(2);
}

/// Load the layered config, exiting with the usage status on any
/// error: a malformed config is fatal so a typo surfaces. Shared by
/// the bench path and the freq command words, which need the
/// declared `[freq]` steady state.
fn load_config_or_exit(named: Option<&std::path::Path>) -> config::Config {
    match config::load(named) {
        Ok((c, _)) => c,
        Err(e) => {
            eprintln!("error: config: {e}");
            std::process::exit(2);
        }
    }
}

/// Banner text listing which config files were loaded, the highest priority first, where
/// `files` is in load order, or `"none (built-in defaults)"` when no file exists.
fn config_summary(files: &[std::path::PathBuf]) -> String {
    if files.is_empty() {
        "none (built-in defaults)".to_string()
    } else {
        files
            .iter()
            .rev()
            .map(|p| run_config::display_path(p))
            .collect::<Vec<_>>()
            .join(", ")
    }
}

/// Wrap a name list into comma-separated lines of at most `width`
/// columns, each line indented two spaces: the no-benches
/// listing's counterpart of clap's two-column help style.
fn wrap_names(names: &[&str], width: usize) -> String {
    let mut out = String::new();
    let mut col = 0;
    for name in names {
        if out.is_empty() {
            out.push_str("  ");
        } else if col + 2 + name.len() <= width {
            out.push_str(", ");
        } else {
            out.push_str(",\n  ");
            col = 0;
        }
        out.push_str(name);
        col += 2 + name.len();
    }
    out
}

fn main() {
    // Shell completion: when the shell set COMPLETE, answer with
    // the candidates and exit before anything else runs.
    CompleteEnv::with_factory(Cli::command).complete();
    let mut cli = Cli::parse();
    if let Err(e) = take_config_arg(&mut cli) {
        eprintln!("error: {e}");
        std::process::exit(2);
    }
    // Refused before any setup, since an exit past the clock pin skips its restore.
    if cli.record.is_some() {
        eprintln!(
            "error: --record is gone, since a path's trailing '/' picked its mode: \
             --record-dir DIR writes a file per invocation, --record-file PATH appends every \
             record to one file"
        );
        std::process::exit(2);
    }

    // The bench-name listing is a pure print-and-exit path: no
    // logging, no config, no setup.
    if cli.list_benches {
        for name in benches::names() {
            println!("{name}");
        }
        return;
    }

    // 'describe-record' is a pure print-and-exit command word: the
    // record's field dictionary, documenting outputs the way
    // --help documents inputs.
    if cli.benches.iter().any(|b| b == "describe-record") {
        if cli.benches.len() > 1 {
            eprintln!("error: 'describe-record' runs alone; drop the other bench args");
            std::process::exit(2);
        }
        println!("{ABOUT}\n");
        record::describe();
        return;
    }

    // 'analyze' reads records and prints: no config, no setup, nothing measured.
    if cli.benches.first().is_some_and(|b| b == "analyze") {
        let trim = match cli.trim_runs.as_deref().map(series::Trim::parse) {
            None => series::Trim::DEFAULT,
            Some(Ok(trim)) => trim,
            Some(Err(e)) => {
                eprintln!("error: analyze: --trim-runs: {e}");
                std::process::exit(2);
            }
        };
        // Records where the sides belong get the line to run, before a bare key could take
        // the path for one.
        let mut compares = Vec::new();
        for spec in &cli.compare {
            if let Some(hint) = analyze::compare_hint(spec) {
                eprintln!("error: analyze: --compare: {hint}");
                std::process::exit(2);
            }
            match analyze::Sides::parse(spec) {
                Ok(sides) => compares.push(sides),
                Err(e) => {
                    eprintln!("error: analyze: --compare: {e}");
                    std::process::exit(2);
                }
            }
        }
        let paths: Vec<std::path::PathBuf> = cli.benches[1..]
            .iter()
            .map(std::path::PathBuf::from)
            .collect();
        std::process::exit(analyze::run(&paths, &cli.by, &compares, trim));
    }
    // 'linear-regression', 'lr' for short, reads records and prints, as 'analyze' does.
    if cli
        .benches
        .first()
        .is_some_and(|b| b == "linear-regression" || b == "lr")
    {
        let trim = match cli.trim_runs.as_deref().map(series::Trim::parse) {
            None => series::Trim::DEFAULT,
            Some(Ok(trim)) => trim,
            Some(Err(e)) => {
                eprintln!("error: linear-regression: --trim-runs: {e}");
                std::process::exit(2);
            }
        };
        if let Some(ns) = cli.overhead.filter(|ns| !ns.is_finite() || *ns < 0.0) {
            eprintln!("error: linear-regression: --overhead: {ns} is not a time in ns");
            std::process::exit(2);
        }
        let paths: Vec<std::path::PathBuf> = cli.benches[1..]
            .iter()
            .map(std::path::PathBuf::from)
            .collect();
        std::process::exit(linear_regression::run(&paths, trim, cli.overhead));
    }
    // 'figures' draws records and exits, reading no config.
    if cli.benches.first().is_some_and(|b| b == "figures") {
        let trim = match cli.trim_runs.as_deref().map(series::Trim::parse) {
            None => series::Trim::DEFAULT,
            Some(Ok(trim)) => trim,
            Some(Err(e)) => {
                eprintln!("error: figures: --trim-runs: {e}");
                std::process::exit(2);
            }
        };
        let show = match cli.show.as_deref().map(figures::Show::parse) {
            None => figures::Show::All,
            Some(Ok(show)) => show,
            Some(Err(e)) => {
                eprintln!("error: figures: --show: {e}");
                std::process::exit(2);
            }
        };
        let x = match cli.x_axis.as_deref().map(figures::XAxis::parse) {
            None => figures::XAxis::Time,
            Some(Ok(x)) => x,
            Some(Err(e)) => {
                eprintln!("error: figures: --x-axis: {e}");
                std::process::exit(2);
            }
        };
        let plan = figures::Plan {
            benches: cli.bench.clone(),
            show,
            x,
            series: cli.series.clone(),
            trim,
        };
        let paths: Vec<std::path::PathBuf> = cli.benches[1..]
            .iter()
            .map(std::path::PathBuf::from)
            .collect();
        let out = match &cli.out {
            Some(out) => out.clone(),
            None => std::path::PathBuf::from("block-means.png"),
        };
        std::process::exit(figures::run(&paths, &plan, &out));
    }
    if !cli.bench.is_empty() || cli.show.is_some() || cli.x_axis.is_some() || cli.out.is_some() {
        eprintln!("error: --bench, --show, --x-axis, and --out belong to 'figures'");
        std::process::exit(2);
    }
    if !cli.by.is_empty() || !cli.compare.is_empty() {
        eprintln!("error: --by and --compare belong to 'analyze'");
        std::process::exit(2);
    }

    // 'read-freq' prints and exits: no root, no config, no banner,
    // so a prompt or status bar can call it every few seconds.
    if cli.benches.iter().any(|b| b == "read-freq") {
        if cli.benches.len() > 1 {
            eprintln!("error: 'read-freq' runs alone; drop the other bench args");
            std::process::exit(2);
        }
        std::process::exit(freqctl::cmd_read_freq(cli.as_config));
    }

    // 'pin-freq' and 'restore-freq' mutate the box on request and
    // exit. Both read the config for the declared [freq] steady
    // state, and pin-freq additionally takes one optional MHZ arg
    // (`pin-freq 3800`).
    if cli.benches.iter().any(|b| b == "pin-freq") {
        if cli.benches[0] != "pin-freq" || cli.benches.len() > 2 {
            eprintln!(
                "error: 'pin-freq' runs alone, with at most one MHZ, pin_mhz, min_mhz, or max_mhz arg"
            );
            std::process::exit(2);
        }
        let target = match config::PinFreq::from_flag(cli.benches.get(1).map(String::as_str)) {
            Ok(config::PinFreq::Off) => {
                eprintln!("error: pin-freq: \"no\" pins nothing; use restore-freq to unpin");
                std::process::exit(2);
            }
            Ok(t) => t,
            Err(e) => {
                eprintln!("error: pin-freq: {e}");
                std::process::exit(2);
            }
        };
        let config = load_config_or_exit(cli.config.as_deref());
        std::process::exit(freqctl::cmd_pin_freq(
            config.freq.as_ref(),
            target,
            config.source("freq"),
        ));
    }
    if cli.benches.iter().any(|b| b == "restore-freq") {
        if cli.benches.len() > 1 {
            eprintln!("error: 'restore-freq' runs alone; drop the other bench args");
            std::process::exit(2);
        }
        let config = load_config_or_exit(cli.config.as_deref());
        std::process::exit(freqctl::cmd_restore_freq(
            config.freq.as_ref(),
            config.source("freq"),
        ));
    }

    // 'update-config FILE' rewrites a config in place from its own values and the line's.
    if cli.benches.iter().any(|b| b == "update-config") {
        if cli.benches[0] != "update-config" || cli.benches.len() != 2 {
            eprintln!("error: 'update-config' runs alone, with the one FILE to rewrite");
            std::process::exit(2);
        }
        if cli.from.is_some() || cli.config.is_some() || cli.from_record.is_some() {
            eprintln!(
                "error: update-config: FILE is the start, so drop --from, --config, and \
                 --from-record"
            );
            std::process::exit(2);
        }
        let line = match line_values(&cli) {
            Ok(table) => table,
            Err(e) => {
                eprintln!("error: update-config: {e}");
                std::process::exit(2);
            }
        };
        std::process::exit(init_config::update(
            std::path::Path::new(&cli.benches[1]),
            cli.backup,
            line,
        ));
    }

    // 'init-config' prints or writes the starting config and exits, with one optional PATH arg.
    if cli.benches.iter().any(|b| b == "init-config") {
        if cli.benches[0] != "init-config" || cli.benches.len() > 2 {
            eprintln!("error: 'init-config' runs alone, with at most one PATH arg");
            std::process::exit(2);
        }
        let starts = [
            cli.from.is_some(),
            cli.config.is_some(),
            cli.from_record.is_some(),
        ];
        if starts.iter().filter(|&&set| set).count() > 1 {
            eprintln!(
                "error: init-config: --from, --config, and --from-record each name what to start \
                 from: keep one"
            );
            std::process::exit(2);
        }
        if cli.series.is_some() && cli.from_record.is_none() {
            eprintln!("error: init-config: --series picks an invocation of --from-record's FILE");
            std::process::exit(2);
        }
        let start = if let Some(old) = cli.from.as_deref() {
            init_config::Start::From(old)
        } else if let Some(name) = cli.config.as_deref() {
            init_config::Start::Named(name)
        } else if let Some(file) = cli.from_record.as_deref() {
            init_config::Start::Record(file, cli.series.as_deref())
        } else {
            init_config::Start::Host
        };
        let line = match line_values(&cli) {
            Ok(table) => table,
            Err(e) => {
                eprintln!("error: init-config: {e}");
                std::process::exit(2);
            }
        };
        let existing = match (cli.backup, cli.overwrite) {
            (true, _) => init_config::Existing::Backup,
            (false, true) => init_config::Existing::Overwrite,
            (false, false) => init_config::Existing::Refuse,
        };
        std::process::exit(init_config::run(
            cli.benches.get(1).map(std::path::Path::new),
            start,
            line,
            existing,
        ));
    }
    if cli.backup || cli.overwrite {
        eprintln!("error: --backup and --overwrite belong to 'init-config' and 'update-config'");
        std::process::exit(2);
    }
    if cli.from.is_some() || cli.from_record.is_some() || cli.series.is_some() {
        eprintln!("error: --from, --from-record, and --series belong to 'init-config'");
        std::process::exit(2);
    }

    // 'setup-freq' prepares the host and exits: it reads the live clock
    // state and the XDG config itself, so it needs neither the
    // layered config nor the banner.
    if cli.benches.iter().any(|b| b == "setup-freq") {
        if cli.benches.len() > 1 {
            eprintln!("error: 'setup-freq' runs alone; drop the other bench args");
            std::process::exit(2);
        }
        std::process::exit(setup::run(cli.apply));
    }
    // 'setup' is setup-freq with the host's placements beside the clock.
    if cli.benches.iter().any(|b| b == "setup") {
        if cli.benches.len() > 1 {
            eprintln!("error: 'setup' runs alone; drop the other bench args");
            std::process::exit(2);
        }
        std::process::exit(setup::run_setup(cli.apply));
    }
    // 'setup-uninstall' gives back what setup took: the udev rule and the cpufreq files.
    if cli.benches.iter().any(|b| b == "setup-uninstall") {
        if cli.benches.len() > 1 {
            eprintln!("error: 'setup-uninstall' runs alone; drop the other bench args");
            std::process::exit(2);
        }
        std::process::exit(setup::run_uninstall(cli.apply));
    }

    // A bench child runs its one bench from the parent's spec and exits: no config, no inhibit,
    // no clock pin, and no banner, all of which the parent owns, its `-v` included.
    if let Some(spec) = &cli.child_spec {
        init_logger(cli.verbose == Some(true));
        std::process::exit(child::child_main(spec));
    }

    // Layered defaults (built-in < XDG file < project-local file <
    // CLI). A malformed config is fatal so a typo surfaces. Loaded
    // before the logger and the inhibit, since `verbose` and
    // `inhibit` are keys.
    let (config, config_files) = match config::load(cli.config.as_deref()) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("error: config: {e}");
            eprintln!("{}", binary_line());
            std::process::exit(2);
        }
    };
    let (verbose, verbose_src) = layered(
        cli.verbose,
        "--verbose",
        config.verbose,
        "verbose",
        &config,
        false,
    );
    init_logger(verbose);

    // Checked here rather than by clap, since `init-config PATH --benches a` is a positional and
    // the flag together, and is how a written file gets its benches.
    if !cli.benches.is_empty() && !cli.benches_flag.is_empty() {
        eprintln!("error: --benches and bench names on the line both name the benches: keep one");
        std::process::exit(2);
    }

    if cli.benches.is_empty() && cli.benches_flag.is_empty() && config.benches.is_none() {
        println!("{ABOUT}\n");
        println!("no benches specified. use -h or --help for more info.\n");
        println!("Benches:");
        println!("{}", wrap_names(&benches::names(), 72));
        return;
    }

    // 'qualify-environment' is a command, not a bench: it respawns
    // --runs times and grades the box across those runs. It stands
    // alone, and it re-execs children itself, so it runs before
    // the inhibit/config/banner path a bench run needs.
    if cli.benches.iter().any(|b| b == "qualify-environment") {
        if cli.benches.len() > 1 {
            eprintln!("error: 'qualify-environment' runs alone; drop the other bench args");
            std::process::exit(2);
