804	/// The config files `typed` could become: the `.md` and `.toml` files in the directory it
805	/// names so far whose names start as it does. None for an empty `typed`, where every README
806	/// in the directory would crowd the bench names.
807	fn config_files(typed: &str) -> Vec<String> {
808	    if typed.is_empty() {
809	        return Vec::new();
810	    }
811	    let (dir, prefix) = match typed.rsplit_once('/') {
812	        Some((dir, prefix)) => (format!("{dir}/"), prefix),
813	        None => (String::new(), typed),
814	    };
815	    let listing = match std::fs::read_dir(if dir.is_empty() { "." } else { &dir }) {
816	        Ok(listing) => listing,
817	        Err(_) => return Vec::new(),
818	    };
819	    let mut files: Vec<String> = listing
820	        .filter_map(|entry| entry.ok()?.file_name().into_string().ok())
821	        .filter(|name| name.starts_with(prefix) && is_config_arg(name))
822	        .map(|name| format!("{dir}{name}"))
823	        .collect();
824	    files.sort();
825	    files
826	}
