2493	/// Seconds as the `Config:` list prints them, zero as `0` rather than `0 us`.
2494	fn seconds_value(s: f64) -> String {
2495	    if s <= 0.0 {
2496	        "0".to_string()
2497	    } else {
2498	        timespec::display(s)
2499	    }
2500	}
